/* ---------- small utilities ---------- */

const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function mergeById(a, b) {
  const m = new Map();
  [...a, ...b].forEach((x) => {
    if (x && x.id && !m.has(x.id)) m.set(x.id, x);
  });
  return [...m.values()].sort((x, y) => (x.ts || 0) - (y.ts || 0));
}

async function loadKey(key) {
  try {
    const r = await fetch(`/api/storage?key=${encodeURIComponent(key)}`);
    if (!r.ok) return [];
    const data = await r.json();
    if (!data || !data.value) return [];
    const parsed = JSON.parse(data.value);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return []; // key does not exist yet, or read failed
  }
}

async function saveKey(key, arr) {
  try {
    const r = await fetch(`/api/storage`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ key, value: JSON.stringify(arr) }),
    });
    return r.ok;
  } catch (e) {
    return false;
  }
}

// Append-only write for keys whose public GET view is redacted (currently
// just registrations, which has emails stripped out). The server merges
// this single entry into the real, unstripped list -- the client never
// reads or re-posts the full array, so it can't clobber other people's
// emails. Returns the resulting public (stripped) list on success, or null
// on failure.
async function appendKey(key, entry) {
  try {
    const r = await fetch(`/api/storage`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ key, entry }),
    });
    if (!r.ok) return null;
    const data = await r.json();
    if (!data || !data.value) return null;
    const parsed = JSON.parse(data.value);
    return Array.isArray(parsed) ? parsed : null;
  } catch (e) {
    return null;
  }
}

// Organizer-only variants: hit the Cloudflare Access-protected endpoint
// instead. If Access hasn't authenticated this browser yet, these calls
// fail (ok: false) rather than silently succeeding.
async function loadOrganizerKey(key) {
  try {
    const r = await fetch(`/api/organizer/storage?key=${encodeURIComponent(key)}`);
    if (!r.ok) return { ok: false, data: [], organizer: null };
    const data = await r.json();
    if (!data || typeof data.value === "undefined") return { ok: false, data: [], organizer: null };
    const parsed = data.value ? JSON.parse(data.value) : [];
    return { ok: true, data: Array.isArray(parsed) ? parsed : [], organizer: data.organizer || null };
  } catch (e) {
    return { ok: false, data: [], organizer: null };
  }
}

async function saveOrganizerKey(key, arr) {
  try {
    const r = await fetch(`/api/organizer/storage`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ key, value: JSON.stringify(arr) }),
    });
    return r.ok;
  } catch (e) {
    return false;
  }
}

function rankValue(rank) {
  if (!rank) return 0;
  const [n, t] = rank.split(" ");
  const num = parseInt(n, 10) || 0;
  return t === "Dan" ? 100 + num : 100 - num;
}

function fmtTime(ts) {
  const d = new Date(ts);
  const now = new Date();
  const sameDay = d.toDateString() === now.toDateString();
  const hm = d.toLocaleTimeString("de-CH", { hour: "2-digit", minute: "2-digit" });
  if (sameDay) return hm;
  return d.toLocaleDateString("de-CH", { weekday: "short", day: "numeric", month: "numeric" }) + " " + hm;
}

